const ip = headers['x-forwarded-for'] || headers['x-real-ip'] || $input.first().json.ip || '';
const userAgent = headers['user-agent'] || '';
return [{ json: { token, ip, user_agent: userAgent, timestamp: $now.toISO() } }];

